function sk1230_checkout(array $d):array{$s=sk1230_settings();if(empty($s['enabled']))throw new RuntimeException('Ordering is unavailable.');$uid=sk1230_uid();if($uid<1&&empty($s['guest_checkout']))throw new RuntimeException('Please sign in to checkout.');$sum=sk1230_cart_summary();if(empty($sum['items']))throw new RuntimeException('Your cart is empty.');$name=mb_substr(trim((string)($d['customer_name']??'')),0,140);$phone=mb_substr(trim((string)($d['customer_phone']??'')),0,60);$email=mb_substr(trim((string)($d['customer_email']??'')),0,190);if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('Enter a valid email address or leave it blank.');$ful=in_array(($d['fulfillment_type']??'delivery'),['delivery','pickup'],true)?$d['fulfillment_type']:'delivery';$address=mb_substr(trim((string)($d['address_text']??'')),0,700);$area=mb_substr(trim((string)($d['area']??'')),0,180);if($name===''||$phone==='')throw new InvalidArgumentException('Name and phone are required.');if($ful==='delivery'&&$address==='')throw new InvalidArgumentException('Delivery address is required.');$pm=(string)($d['payment_method']??'cod');$allowed=[];if(!empty($s['cod_enabled']))$allowed[]='cod';if(!empty($s['advance_enabled']))$allowed[]='advance';if(!empty($s['wallet_enabled'])&&$uid>0)$allowed[]='wallet';if(!in_array($pm,$allowed,true))throw new RuntimeException('Selected payment method is unavailable.');$scheduled=null;if(!empty($d['scheduled_for'])){if(empty($s['scheduled_orders']))throw new RuntimeException('Scheduled orders are disabled.');$ts=strtotime((string)$d['scheduled_for']);if(!$ts||$ts<time()+1800)throw new RuntimeException('Scheduled time must be at least 30 minutes from now.');$scheduled=date('Y-m-d H:i:s',$ts);}
