$membership=$uid>0?sk1230_active_membership($uid):[];$delivery=0;$groupFees=[];foreach($sum['groups'] as $g){$fee=$ful==='delivery'?sk1230_zone_fee((int)$g['business_id'],$area,(float)$g['subtotal']):0;if($membership&&$ful==='delivery'&&(float)$membership['free_delivery_min']>0&&(float)$g['subtotal']>=(float)$membership['free_delivery_min'])$fee=0;$groupFees[(int)$g['business_id']]=$fee;$delivery+=$fee;}$coupon=sk1230_coupon((string)($d['coupon_code']??''),$sum['groups']);$discount=(float)$coupon['discount'];$grand=max(0,(float)$sum['subtotal']+$delivery-$discount);$walletUsed=0;if($pm==='wallet'){if($uid<1)throw new RuntimeException('Wallet requires sign in.');$bal=sk1230_wallet($uid);if($bal+0.001<$grand)throw new RuntimeException('Wallet balance is insufficient. Available: '.sk1230_money($bal));$walletUsed=$grand;}
$pdo=db();$pdo->beginTransaction();try{$orderNo='SK'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$token=bin2hex(random_bytes(24));$status=$pm==='advance'?'awaiting_payment':'placed';$payStatus=$pm==='wallet'?'paid':'pending';$q=$pdo->prepare('INSERT INTO commerce_orders_v1230(tenant_id,order_no,public_token,user_id,visitor_key,customer_name,customer_phone,customer_email,address_text,area,fulfillment_type,scheduled_for,subtotal,delivery_fee,discount_total,wallet_used,grand_total,coupon_code,payment_method,payment_status,status,customer_notes,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())');$q->execute([sk1230_tid(),$orderNo,$token,$uid?:null,sk1230_visitor_key(),$name,$phone,$email?:null,$address?:null,$area?:null,$ful,$scheduled,(float)$sum['subtotal'],$delivery,$discount,$walletUsed,$grand,$coupon['code']?:null,$pm,$payStatus,$status,mb_substr(trim((string)($d['customer_notes']??'')),0,1200)]);$oid=(int)$pdo->lastInsertId();
$discountRemain=$discount;foreach($sum['groups'] as $gi=>$g){$bid=(int)$g['business_id'];$gdisc=0;if($discount>0&&((int)($coupon['business_id']??0)===0||(int)($coupon['business_id']??0)===$bid)){if((int)($coupon['business_id']??0)===0)$gdisc=min($discountRemain,$discount*((float)$g['subtotal']/max(0.01,(float)$sum['subtotal'])));else $gdisc=min($discountRemain,$discount);$discountRemain-=$gdisc;}$gt=max(0,(float)$g['subtotal']+$groupFees[$bid]-$gdisc);$pdo->prepare('INSERT INTO commerce_order_groups_v1230(tenant_id,order_id,business_id,subtotal,delivery_fee,discount_total,total,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?, ?,NOW(),NOW())')->execute([sk1230_tid(),$oid,$bid,(float)$g['subtotal'],$groupFees[$bid],$gdisc,$gt,$status]);$gid=(int)$pdo->lastInsertId();foreach($g['items'] as $it){$line=(float)$it['unit_price']*(int)$it['qty'];$pdo->prepare('INSERT INTO commerce_order_items_v1230(tenant_id,order_id,order_group_id,product_id,business_id,product_name,image_url,unit_price,qty,line_total,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,NOW())')->execute([sk1230_tid(),$oid,$gid,(int)$it['product_id'],$bid,$it['product_name'],$it['image_url']?:null,(float)$it['unit_price'],(int)$it['qty'],$line]);$p=sk1230_product((int)$it['product_id']);[$stockCol,$stock]=sk1230_stock_info($p);if($stockCol!==''&&in_array($stockCol,['stock_qty','inventory_qty'],true)){$stq=$pdo->prepare('UPDATE store_products SET `'.$stockCol.'`=`'.$stockCol.'`-? WHERE id=? AND `'.$stockCol.'`>=?');$stq->execute([(int)$it['qty'],(int)$it['product_id'],(int)$it['qty']]);if($stq->rowCount()<1)throw new RuntimeException('Stock changed during checkout for '.$it['product_name'].'. Please try again.'); }}$pdo->prepare('INSERT INTO commerce_order_status_log_v1230(tenant_id,order_id,order_group_id,status,actor_user_id,note,created_at) VALUES(?,?,?,?,?,?,NOW())')->execute([sk1230_tid(),$oid,$gid,$status,$uid?:null,'Order placed']);}
