$pdo->prepare("UPDATE commerce_carts_v1230 SET status='converted',updated_at=NOW() WHERE id=?")->execute([(int)$sum['cart']['id']]);$pdo->commit();sk1230_notify($uid?:null,sk1230_visitor_key(),'Order '.$orderNo.' placed','Your ShahkotPK order has been created. Track seller preparation and delivery from My Orders.','/order-track-v1230.php?token='.$token,'order_placed');if($uid>0&&!empty($d['save_address']))sk1230_save_address($d);return ['id'=>$oid,'order_no'=>$orderNo,'token'=>$token,'grand_total'=>$grand,'status'=>$status];}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}

function sk1230_order(int $id=0,string $token=''):array{if(!sk1230_table('commerce_orders_v1230'))return [];try{$w=['tenant_id=?'];$p=[sk1230_tid()];if($id>0){$w[]='id=?';$p[]=$id;}elseif($token!==''){$w[]='public_token=?';$p[]=$token;}else return [];$q=db()->prepare('SELECT * FROM commerce_orders_v1230 WHERE '.implode(' AND ',$w).' LIMIT 1');$q->execute($p);$o=$q->fetch()?:[];if(!$o)return [];$q=db()->prepare('SELECT g.*,b.name business_name FROM commerce_order_groups_v1230 g LEFT JOIN businesses b ON b.id=g.business_id WHERE g.order_id=? ORDER BY g.id');$q->execute([(int)$o['id']]);$o['groups']=$q->fetchAll()?:[];foreach($o['groups'] as &$g){$q=db()->prepare('SELECT * FROM commerce_order_items_v1230 WHERE order_group_id=? ORDER BY id');$q->execute([(int)$g['id']]);$g['items']=$q->fetchAll()?:[];$q=db()->prepare('SELECT a.*,r.name rider_name,r.phone rider_phone,r.vehicle_type,r.vehicle_no,r.location_updated_at FROM delivery_assignments_v1230 a LEFT JOIN delivery_riders_v1230 r ON r.id=a.rider_id WHERE a.order_group_id=? LIMIT 1');$q->execute([(int)$g['id']]);$g['delivery']=$q->fetch()?:[];}$q=db()->prepare('SELECT * FROM commerce_order_status_log_v1230 WHERE order_id=? ORDER BY id');$q->execute([(int)$o['id']]);$o['timeline']=$q->fetchAll()?:[];return $o;}catch(Throwable $e){return [];} }
function sk1230_can_view_order(array $o):bool{if(!$o)return false;$reqToken=preg_replace('/[^a-f0-9]/','',(string)($_GET['token']??$_POST['token']??''));if($reqToken!==''&&!empty($o['public_token'])&&hash_equals((string)$o['public_token'],$reqToken))return true;$uid=sk1230_uid();if($uid>0&&(int)($o['user_id']??0)===$uid)return true;if((string)($o['visitor_key']??'')===sk1230_visitor_key())return true;return false;}
function sk1230_my_orders(int $limit=100):array{$tid=sk1230_tid();$uid=sk1230_uid();$vk=sk1230_visitor_key();try{$q=db()->prepare('SELECT * FROM commerce_orders_v1230 WHERE tenant_id=? AND '.($uid>0?'user_id=?':'user_id IS NULL AND visitor_key=?').' ORDER BY id DESC LIMIT '.max(1,min(200,$limit)));$q->execute([$tid,$uid>0?$uid:$vk]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];} }
function sk1230_reorder(int $orderId):int{$o=sk1230_order($orderId);if(!$o||!sk1230_can_view_order($o))throw new RuntimeException('Order not found.');$n=0;foreach($o['groups'] as $g)foreach($g['items'] as $it){try{sk1230_cart_add((int)$it['product_id'],(int)$it['qty']);$n++;}catch(Throwable $e){}}if($n<1)throw new RuntimeException('No products from this order are currently orderable.');return $n;}
function sk1230_favorite_order(int $orderId,string $label='Favorite Order'):void{$uid=sk1230_uid();if($uid<1)throw new RuntimeException('Sign in to save favorite orders.');$o=sk1230_order($orderId);if(!$o||(int)$o['user_id']!==$uid)throw new RuntimeException('Order not found.');db()->prepare('INSERT INTO commerce_favorite_orders_v1230(tenant_id,user_id,source_order_id,label,created_at) VALUES(?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE label=VALUES(label)')->execute([sk1230_tid(),$uid,$orderId,mb_substr(trim($label)?:'Favorite Order',0,140)]);}
function sk1230_favorites():array{$uid=sk1230_uid();if($uid<1)return [];try{$q=db()->prepare('SELECT f.*,o.order_no,o.grand_total,o.created_at order_created FROM commerce_favorite_orders_v1230 f JOIN commerce_orders_v1230 o ON o.id=f.source_order_id WHERE f.tenant_id=? AND f.user_id=? ORDER BY f.id DESC');$q->execute([sk1230_tid(),$uid]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];} }

function sk1230_business_ids_for_user(int $uid):array{if($uid<1||!sk1230_table('businesses'))return [];$cols=sk1230_cols('businesses');$parts=[];$p=[];foreach(['owner_user_id','owner_id'] as $c)if(in_array($c,$cols,true)){$parts[]='`'.$c.'`=?';$p[]=$uid;}if(!$parts)return [];try{$q=db()->prepare('SELECT id FROM businesses WHERE '.implode(' OR ',$parts));$q->execute($p);return array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN)?:[]);}catch(Throwable $e){return [];} }
function sk1230_business_orders(int $uid):array{$ids=sk1230_business_ids_for_user($uid);if(!$ids)return [];$ph=implode(',',array_fill(0,count($ids),'?'));try{$q=db()->prepare("SELECT g.*,o.order_no,o.customer_name,o.customer_phone,o.fulfillment_type,o.scheduled_for,o.payment_method,o.payment_status,o.address_text,o.area,o.public_token,b.name business_name FROM commerce_order_groups_v1230 g JOIN commerce_orders_v1230 o ON o.id=g.order_id LEFT JOIN businesses b ON b.id=g.business_id WHERE g.tenant_id=? AND g.business_id IN ($ph) ORDER BY FIELD(g.status,'placed','accepted','preparing','ready','out_for_delivery','delivered','cancelled'),g.id DESC LIMIT 300");$q->execute(array_merge([sk1230_tid()],$ids));return $q->fetchAll()?:[];}catch(Throwable $e){return [];} }
function sk1230_group_set_status(int $gid,string $status,int $uid,int $prep=0,string $note=''):void{$allowed=['accepted','preparing','ready','out_for_delivery','delivered','cancelled'];if(!in_array($status,$allowed,true))throw new InvalidArgumentException('Invalid status.');$ids=sk1230_business_ids_for_user($uid);if(!$ids)throw new RuntimeException('No business attached.');$ph=implode(',',array_fill(0,count($ids),'?'));$q=db()->prepare("SELECT g.*,o.payment_method,o.payment_status,o.user_id,o.visitor_key,o.order_no,o.public_token FROM commerce_order_groups_v1230 g JOIN commerce_orders_v1230 o ON o.id=g.order_id WHERE g.id=? AND g.business_id IN ($ph) LIMIT 1");$q->execute(array_merge([$gid],$ids));$g=$q->fetch();if(!$g)throw new RuntimeException('Order group not found.');if($g['payment_method']==='advance'&&$g['payment_status']!=='paid'&&$status!=='cancelled')throw new RuntimeException('Advance payment is not confirmed yet.');$extra='';if($status==='accepted')$extra=',accepted_at=NOW()';if($status==='ready')$extra=',ready_at=NOW()';if($status==='out_for_delivery')$extra=',dispatched_at=NOW()';if($status==='delivered')$extra=',delivered_at=NOW()';db()->prepare('UPDATE commerce_order_groups_v1230 SET status=?,prep_minutes=?,updated_at=NOW()'.$extra.' WHERE id=?')->execute([$status,max(0,min(360,$prep)),$gid]);db()->prepare('INSERT INTO commerce_order_status_log_v1230(tenant_id,order_id,order_group_id,status,actor_user_id,note,created_at) VALUES(?,?,?,?,?,?,NOW())')->execute([sk1230_tid(),(int)$g['order_id'],$gid,$status,$uid,mb_substr($note,0,700)]);sk1230_sync_order_status((int)$g['order_id']);sk1230_notify(!empty($g['user_id'])?(int)$g['user_id']:null,(string)$g['visitor_key'],'Order '.$g['order_no'].' updated',sk1230_business_name((int)$g['business_id']).' is now '.str_replace('_',' ',$status).'.','/order-track-v1230.php?token='.$g['public_token'],'order_status');}
function sk1230_sync_order_status(int $orderId):void{$q=db()->prepare('SELECT status FROM commerce_order_groups_v1230 WHERE order_id=?');$q->execute([$orderId]);$s=$q->fetchAll(PDO::FETCH_COLUMN)?:[];if(!$s)return;$status='placed';if(count(array_unique($s))===1)$status=(string)$s[0];elseif(in_array('out_for_delivery',$s,true))$status='out_for_delivery';elseif(in_array('ready',$s,true))$status='partially_ready';elseif(in_array('preparing',$s,true)||in_array('accepted',$s,true))$status='processing';elseif(!array_diff($s,['delivered','cancelled']))$status=in_array('delivered',$s,true)?'delivered':'cancelled';db()->prepare('UPDATE commerce_orders_v1230 SET status=?,updated_at=NOW() WHERE id=?')->execute([$status,$orderId]);if($status==='delivered')sk1230_finalize_rewards($orderId);}
function sk1230_finalize_rewards(int $orderId):void{$q=db()->prepare('SELECT * FROM commerce_orders_v1230 WHERE id=? AND rewards_awarded_at IS NULL LIMIT 1');$q->execute([$orderId]);$o=$q->fetch();if(!$o)return;$uid=(int)($o['user_id']??0);if($uid<1){db()->prepare('UPDATE commerce_orders_v1230 SET rewards_awarded_at=NOW() WHERE id=?')->execute([$orderId]);return;}$m=sk1230_active_membership($uid);$mult=$m?max(1,(float)$m['points_multiplier']):1;$points=(int)floor(((float)$o['grand_total']/100)*max(0,(int)sk1230_settings()['points_per_100'])*$mult);if($points>0&&sk1230_table('local_loyalty_accounts_v1050')){db()->prepare('INSERT INTO local_loyalty_accounts_v1050(tenant_id,user_id,points_balance,lifetime_points,updated_at,created_at) VALUES(?,?,?,?,NOW(),NOW()) ON DUPLICATE KEY UPDATE points_balance=points_balance+VALUES(points_balance),lifetime_points=lifetime_points+VALUES(lifetime_points),updated_at=NOW()')->execute([sk1230_tid(),$uid,$points,$points]);if(sk1230_table('local_loyalty_ledger_v1050'))db()->prepare('INSERT INTO local_loyalty_ledger_v1050(tenant_id,user_id,event_key,points,reference_type,reference_id,note,created_at) VALUES(?,?,?,?,?,?,?,NOW())')->execute([sk1230_tid(),$uid,'commerce_order',$points,'order',$orderId,'Order reward points']);}$cash=$m?max(0,(float)$m['cashback_percent']):0;if($cash>0){$credit=round((float)$o['grand_total']*$cash/100,2);if($credit>0)sk1230_wallet_change($uid,$credit,'membership_cashback','order',$orderId,'ShahkotPK Plus cashback');}db()->prepare('UPDATE commerce_orders_v1230 SET rewards_awarded_at=NOW() WHERE id=?')->execute([$orderId]);}

function sk1230_riders(bool $activeOnly=false):array{try{$q=db()->prepare('SELECT * FROM delivery_riders_v1230 WHERE tenant_id=?'.($activeOnly?' AND active=1':'').' ORDER BY active DESC,name');$q->execute([sk1230_tid()]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];} }
function sk1230_rider_for_user(int $uid):array{if($uid<1)return [];try{$q=db()->prepare('SELECT * FROM delivery_riders_v1230 WHERE tenant_id=? AND user_id=? AND active=1 LIMIT 1');$q->execute([sk1230_tid(),$uid]);return $q->fetch()?:[];}catch(Throwable $e){return [];} }
function sk1230_save_rider(array $d):void{$id=(int)($d['rider_id']??0);$uid=(int)($d['user_id']??0);$name=mb_substr(trim((string)($d['name']??'')),0,140);$phone=mb_substr(trim((string)($d['phone']??'')),0,60);if($name===''||$phone==='')throw new InvalidArgumentException('Rider name and phone are required.');if($id>0)db()->prepare('UPDATE delivery_riders_v1230 SET user_id=?,name=?,phone=?,vehicle_type=?,vehicle_no=?,zone_label=?,active=?,updated_at=NOW() WHERE id=? AND tenant_id=?')->execute([$uid?:null,$name,$phone,mb_substr(trim((string)($d['vehicle_type']??'')),0,60),mb_substr(trim((string)($d['vehicle_no']??'')),0,80),mb_substr(trim((string)($d['zone_label']??'')),0,180),!empty($d['active'])?1:0,$id,sk1230_tid()]);else db()->prepare('INSERT INTO delivery_riders_v1230(tenant_id,user_id,name,phone,vehicle_type,vehicle_no,zone_label,status,active,created_at,updated_at) VALUES(?,?,?,?,?,?,?,\'offline\',?,NOW(),NOW())')->execute([sk1230_tid(),$uid?:null,$name,$phone,mb_substr(trim((string)($d['vehicle_type']??'')),0,60),mb_substr(trim((string)($d['vehicle_no']??'')),0,80),mb_substr(trim((string)($d['zone_label']??'')),0,180),!empty($d['active'])?1:0]);}
function sk1230_assign_rider(int $gid,int $riderId,int $actor,int $eta=0):void{$q=db()->prepare('SELECT g.*,o.payment_method,o.payment_status,o.user_id,o.visitor_key,o.order_no,o.public_token FROM commerce_order_groups_v1230 g JOIN commerce_orders_v1230 o ON o.id=g.order_id WHERE g.id=? AND g.tenant_id=? LIMIT 1');$q->execute([$gid,sk1230_tid()]);$g=$q->fetch();if(!$g)throw new RuntimeException('Order group not found.');$q=db()->prepare('SELECT * FROM delivery_riders_v1230 WHERE id=? AND tenant_id=? AND active=1 LIMIT 1');$q->execute([$riderId,sk1230_tid()]);if(!$q->fetch())throw new RuntimeException('Rider not found.');db()->prepare('INSERT INTO delivery_assignments_v1230(tenant_id,order_group_id,rider_id,status,eta_minutes,assigned_by,assigned_at,updated_at) VALUES(?,?,?,\'assigned\',?,?,NOW(),NOW()) ON DUPLICATE KEY UPDATE rider_id=VALUES(rider_id),status=\'assigned\',eta_minutes=VALUES(eta_minutes),assigned_by=VALUES(assigned_by),assigned_at=NOW(),updated_at=NOW()')->execute([sk1230_tid(),$gid,$riderId,max(0,min(600,$eta)),$actor]);db()->prepare('UPDATE commerce_order_groups_v1230 SET rider_id=?,updated_at=NOW() WHERE id=?')->execute([$riderId,$gid]);sk1230_notify(!empty($g['user_id'])?(int)$g['user_id']:null,(string)$g['visitor_key'],'Rider assigned to '.$g['order_no'],'A rider has been assigned to '.sk1230_business_name((int)$g['business_id']).' fulfillment.','/order-track-v1230.php?token='.$g['public_token'],'rider_assigned');if($g['payment_method']==='cod')db()->prepare('INSERT INTO delivery_cod_settlements_v1230(tenant_id,rider_id,order_group_id,amount,status,created_at) VALUES(?,?,?,?,\'pending\',NOW()) ON DUPLICATE KEY UPDATE rider_id=VALUES(rider_id),amount=VALUES(amount)')->execute([sk1230_tid(),$riderId,$gid,(float)$g['total']]);}
function sk1230_rider_jobs(int $riderId):array{try{$q=db()->prepare("SELECT a.*,g.order_id,g.business_id,g.status group_status,g.total,o.order_no,o.customer_name,o.customer_phone,o.address_text,o.area,o.fulfillment_type,o.payment_method,o.payment_status,b.name business_name FROM delivery_assignments_v1230 a JOIN commerce_order_groups_v1230 g ON g.id=a.order_group_id JOIN commerce_orders_v1230 o ON o.id=g.order_id LEFT JOIN businesses b ON b.id=g.business_id WHERE a.tenant_id=? AND a.rider_id=? AND a.status NOT IN ('delivered','cancelled') ORDER BY FIELD(a.status,'picked_up','assigned'),a.id DESC");$q->execute([sk1230_tid(),$riderId]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];} }
function sk1230_rider_job_status(int $assignmentId,int $riderId,string $status,string $proof=''):void{$allowed=['accepted','picked_up','delivered'];if(!in_array($status,$allowed,true))throw new InvalidArgumentException('Invalid delivery status.');$q=db()->prepare('SELECT a.*,g.order_id,g.business_id,o.user_id,o.visitor_key,o.order_no,o.public_token FROM delivery_assignments_v1230 a JOIN commerce_order_groups_v1230 g ON g.id=a.order_group_id JOIN commerce_orders_v1230 o ON o.id=g.order_id WHERE a.id=? AND a.rider_id=? AND a.tenant_id=? LIMIT 1');$q->execute([$assignmentId,$riderId,sk1230_tid()]);$a=$q->fetch();if(!$a)throw new RuntimeException('Delivery job not found.');$extra='';if($status==='picked_up')$extra=',picked_at=NOW()';if($status==='delivered')$extra=',delivered_at=NOW(),proof_code=?';if($status==='delivered')db()->prepare('UPDATE delivery_assignments_v1230 SET status=?,updated_at=NOW()'.$extra.' WHERE id=?')->execute([$status,mb_substr(trim($proof),0,40),$assignmentId]);else db()->prepare('UPDATE delivery_assignments_v1230 SET status=?,updated_at=NOW()'.$extra.' WHERE id=?')->execute([$status,$assignmentId]);$gs=$status==='picked_up'?'out_for_delivery':($status==='delivered'?'delivered':'ready');$x='';if($gs==='out_for_delivery')$x=',dispatched_at=NOW()';if($gs==='delivered')$x=',delivered_at=NOW()';db()->prepare('UPDATE commerce_order_groups_v1230 SET status=?,updated_at=NOW()'.$x.' WHERE id=?')->execute([$gs,(int)$a['order_group_id']]);db()->prepare('INSERT INTO commerce_order_status_log_v1230(tenant_id,order_id,order_group_id,status,actor_user_id,note,created_at) VALUES(?,?,?,?,NULL,?,NOW())')->execute([sk1230_tid(),(int)$a['order_id'],(int)$a['order_group_id'],$gs,'Rider update']);sk1230_sync_order_status((int)$a['order_id']);sk1230_notify(!empty($a['user_id'])?(int)$a['user_id']:null,(string)$a['visitor_key'],'Delivery update · '.$a['order_no'],sk1230_business_name((int)$a['business_id']).' is now '.str_replace('_',' ',$gs).'.','/order-track-v1230.php?token='.$a['public_token'],'delivery_status');}
function sk1230_rider_location(int $riderId,float $lat,float $lng):void{if($lat<-90||$lat>90||$lng<-180||$lng>180)throw new InvalidArgumentException('Invalid location.');db()->prepare("UPDATE delivery_riders_v1230 SET current_lat=?,current_lng=?,location_updated_at=NOW(),status='online',updated_at=NOW() WHERE id=? AND tenant_id=?")->execute([$lat,$lng,$riderId,sk1230_tid()]);}

function sk1230_return_request(int $orderId,string $reason,string $details=''):void{$s=sk1230_settings();if(empty($s['returns_enabled']))throw new RuntimeException('Returns are disabled.');$o=sk1230_order($orderId);if(!$o||!sk1230_can_view_order($o))throw new RuntimeException('Order not found.');if(!in_array($o['status'],['delivered','partially_delivered'],true))throw new RuntimeException('Return requests are available after delivery.');db()->prepare("INSERT INTO commerce_returns_v1230(tenant_id,order_id,user_id,reason,details,status,created_at,updated_at) VALUES(?,?,?,?,?,'requested',NOW(),NOW())")->execute([sk1230_tid(),$orderId,sk1230_uid()?:null,mb_substr(trim($reason),0,120),mb_substr(trim($details),0,1200)]);}
function sk1230_dispute_request(int $orderId,string $subject,string $details):void{$s=sk1230_settings();if(empty($s['disputes_enabled']))throw new RuntimeException('Disputes are disabled.');$o=sk1230_order($orderId);if(!$o||!sk1230_can_view_order($o))throw new RuntimeException('Order not found.');if(trim($subject)===''||trim($details)==='')throw new InvalidArgumentException('Subject and details are required.');db()->prepare("INSERT INTO commerce_disputes_v1230(tenant_id,order_id,user_id,subject,details,status,created_at,updated_at) VALUES(?,?,?,?,?,'open',NOW(),NOW())")->execute([sk1230_tid(),$orderId,sk1230_uid()?:null,mb_substr(trim($subject),0,190),mb_substr(trim($details),0,1600)]);}
function sk1230_admin_orders(int $limit=300):array{try{$q=db()->prepare('SELECT o.*,COUNT(g.id) seller_count FROM commerce_orders_v1230 o LEFT JOIN commerce_order_groups_v1230 g ON g.order_id=o.id WHERE o.tenant_id=? GROUP BY o.id ORDER BY o.id DESC LIMIT '.max(1,min(500,$limit)));$q->execute([sk1230_tid()]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];} }
function sk1230_admin_groups(int $limit=300):array{try{$q=db()->prepare('SELECT g.*,o.order_no,o.customer_name,o.customer_phone,o.payment_method,o.payment_status,b.name business_name FROM commerce_order_groups_v1230 g JOIN commerce_orders_v1230 o ON o.id=g.order_id LEFT JOIN businesses b ON b.id=g.business_id WHERE g.tenant_id=? ORDER BY g.id DESC LIMIT '.max(1,min(500,$limit)));$q->execute([sk1230_tid()]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];} }
function sk1230_admin_stats():array{$o=['orders'=>0,'sales'=>0,'active'=>0,'members'=>0,'riders'=>0,'disputes'=>0,'returns'=>0];try{$q=db()->prepare("SELECT COUNT(*),COALESCE(SUM(grand_total),0),SUM(status NOT IN ('delivered','cancelled')) FROM commerce_orders_v1230 WHERE tenant_id=?");$q->execute([sk1230_tid()]);$r=$q->fetch(PDO::FETCH_NUM);$o['orders']=(int)($r[0]??0);$o['sales']=(float)($r[1]??0);$o['active']=(int)($r[2]??0);$q=db()->prepare("SELECT COUNT(*) FROM membership_subscriptions_v1230 WHERE tenant_id=? AND status='active' AND (ends_at IS NULL OR ends_at>=NOW())");$q->execute([sk1230_tid()]);$o['members']=(int)$q->fetchColumn();$q=db()->prepare('SELECT COUNT(*) FROM delivery_riders_v1230 WHERE tenant_id=? AND active=1');$q->execute([sk1230_tid()]);$o['riders']=(int)$q->fetchColumn();$q=db()->prepare("SELECT COUNT(*) FROM commerce_disputes_v1230 WHERE tenant_id=? AND status='open'");$q->execute([sk1230_tid()]);$o['disputes']=(int)$q->fetchColumn();$q=db()->prepare("SELECT COUNT(*) FROM commerce_returns_v1230 WHERE tenant_id=? AND status='requested'");$q->execute([sk1230_tid()]);$o['returns']=(int)$q->fetchColumn();}catch(Throwable $e){}return $o;}
function sk1230_customer_stats():array{$uid=sk1230_uid();$vk=sk1230_visitor_key();$o=['orders'=>0,'active'=>0,'wallet'=>0,'member'=>'','cart'=>sk1230_cart_count(),'alerts'=>0];try{$q=db()->prepare('SELECT COUNT(*),SUM(status NOT IN (\'delivered\',\'cancelled\')) FROM commerce_orders_v1230 WHERE tenant_id=? AND '.($uid>0?'user_id=?':'user_id IS NULL AND visitor_key=?'));$q->execute([sk1230_tid(),$uid>0?$uid:$vk]);$r=$q->fetch(PDO::FETCH_NUM);$o['orders']=(int)($r[0]??0);$o['active']=(int)($r[1]??0);if($uid>0)$o['wallet']=sk1230_wallet($uid);$m=$uid>0?sk1230_active_membership($uid):[];$o['member']=$m?(string)$m['plan_name']:'';$q=db()->prepare('SELECT COUNT(*) FROM commerce_notifications_v1230 WHERE tenant_id=? AND read_at IS NULL AND '.($uid>0?'user_id=?':'user_id IS NULL AND visitor_key=?'));$q->execute([sk1230_tid(),$uid>0?$uid:$vk]);$o['alerts']=(int)$q->fetchColumn();}catch(Throwable $e){}return $o;}
function sk1230_notifications(int $limit=20):array{$uid=sk1230_uid();$vk=sk1230_visitor_key();try{$q=db()->prepare('SELECT * FROM commerce_notifications_v1230 WHERE tenant_id=? AND '.($uid>0?'user_id=?':'user_id IS NULL AND visitor_key=?').' ORDER BY id DESC LIMIT '.max(1,min(100,$limit)));$q->execute([sk1230_tid(),$uid>0?$uid:$vk]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function sk1230_mark_notifications_read():void{$uid=sk1230_uid();$vk=sk1230_visitor_key();try{$q=db()->prepare('UPDATE commerce_notifications_v1230 SET read_at=COALESCE(read_at,NOW()) WHERE tenant_id=? AND '.($uid>0?'user_id=?':'user_id IS NULL AND visitor_key=?').' AND read_at IS NULL');$q->execute([sk1230_tid(),$uid>0?$uid:$vk]);}catch(Throwable $e){}}
function sk1230_notify(?int $uid,string $vk,string $title,string $body,string $url,string $event):void{try{db()->prepare('INSERT INTO commerce_notifications_v1230(tenant_id,user_id,visitor_key,title,body,target_url,event_key,created_at) VALUES(?,?,?,?,?,?,?,NOW())')->execute([sk1230_tid(),$uid,$vk,mb_substr($title,0,190),mb_substr($body,0,700),mb_substr($url,0,700),mb_substr($event,0,60)]);}catch(Throwable $e){}}
}
